 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    blocks = []
    # Each solid 3x3 color block emits a full row and column through its center.
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color == 0:
                continue
            if all(grid[rr][cc] == color
                   for rr in range(r, r + 3) for cc in range(c, c + 3)):
                blocks.append((r + 1, c + 1, color))
    # De-duplicate overlapping detections (normally each solid block is unique).
    blocks = list(dict.fromkeys(blocks))
    horizontal = {}
    vertical = {}
    for r, c, color in blocks:
        horizontal.setdefault(r, set()).add(color)
        vertical.setdefault(c, set()).add(color)
    for r, colors in horizontal.items():
        for c in range(w):
            out[r][c] = next(iter(colors)) if len(colors) == 1 else 0
    for c, colors in vertical.items():
        for r in range(h):
            out[r][c] = next(iter(colors)) if len(colors) == 1 else 0
    # Crossings of rays belonging to different colored blocks are left empty.
    for r in horizontal:
        for c in vertical:
            hc = horizontal[r]
            vc = vertical[c]
            if len(hc) != 1 or len(vc) != 1 or hc != vc:
                out[r][c] = 0
    return out
